/**
 * Dependency-free console contract smoke tests. Run: node tests/test_dashboard.mjs
 *
 * Requires Node 18+ and the project's Python 3.11+ interpreter (PYTHON may override
 * python3). Fixtures are generated by the real backend using in-memory stores.
 * The intentionally small DOM adapter checks rendering and interactions, not
 * browser layout, accessibility-tree fidelity, CSS, or CSP enforcement.
 */
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { delimiter, dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const staticDirectory = join(root, 'src', 'ops_agent', 'static');
const markup = readFileSync(join(staticDirectory, 'index.html'), 'utf8');
const app = readFileSync(join(staticDirectory, 'app.js'), 'utf8');
const fixtureScript = `
import json, random
from ops_agent.demo import inject, seed, SCENARIOS
from ops_agent.engine import Engine
from ops_agent.storage import Store
fixtures = {}
for scenario in SCENARIOS:
    store = Store()
    try:
        engine = Engine(store)
        rng = random.Random(42)
        seed(engine, rng)
        fixtures[scenario] = inject(engine, scenario, rng)
    finally:
        store.close()
store = Store()
try:
    engine = Engine(store)
    rng = random.Random(42)
    seed(engine, rng)
    inject(engine, 'cascade', rng)
    fixtures['recovered'] = inject(engine, 'healthy', rng)
finally:
    store.close()
print(json.dumps(fixtures))
`;
const fixtures = JSON.parse(execFileSync(process.env.PYTHON || 'python3', ['-c', fixtureScript], {
  cwd: root,
  env: {
    ...process.env,
    PYTHONDONTWRITEBYTECODE: '1',
    PYTHONPATH: [join(root, 'src'), process.env.PYTHONPATH].filter(Boolean).join(delimiter),
  },
  encoding: 'utf8',
  timeout: 15000,
  maxBuffer: 2 * 1024 * 1024,
}));

class Element {
  constructor(tagName = 'div', initialText = null) {
    this.tagName = tagName;
    this.attributes = {};
    this.children = [];
    this.parent = null;
    this.style = {};
    this.events = {};
    this.hidden = false;
    this.disabled = false;
    this.dataset = {};
    this.literalText = initialText;
    this.classList = {
      contains: (name) => this.className.split(/\s+/).includes(name),
      toggle: (name, force) => {
        const classes = new Set(this.className.split(/\s+/).filter(Boolean));
        const include = force === undefined ? !classes.has(name) : force;
        if (include) classes.add(name);
        else classes.delete(name);
        this.className = [...classes].join(' ');
        return include;
      },
    };
  }
  get className() { return this.attributes.class || ''; }
  set className(value) { this.attributes.class = value; }
  get id() { return this.attributes.id; }
  set id(value) { this.attributes.id = value; }
  get childNodes() { return this.children; }
  get textContent() { return (this.literalText ?? '') + this.children.map((child) => child.textContent).join(''); }
  set textContent(value) {
    for (const child of this.children) child.parent = null;
    this.children = [];
    this.literalText = String(value);
  }
  setAttribute(name, value) {
    this.attributes[name] = String(value);
    if (name.startsWith('data-')) {
      this.dataset[name.slice(5).replace(/-([a-z])/g, (_, letter) => letter.toUpperCase())] = String(value);
    }
  }
  getAttribute(name) { return this.attributes[name] ?? null; }
  removeAttribute(name) { delete this.attributes[name]; }
  append(...items) {
    for (let item of items) {
      if (typeof item === 'string') item = new Element('#text', item);
      if (item.tagName === '#fragment') { this.append(...item.children); continue; }
      item.parent = this;
      this.children.push(item);
    }
  }
  replaceChildren(...items) {
    for (const child of this.children) child.parent = null;
    this.children = [];
    this.literalText = null;
    this.append(...items);
  }
  addEventListener(name, handler) { (this.events[name] ??= []).push(handler); }
  async click() {
    if (this.disabled) return;
    document.activeElement = this;
    for (const handler of this.events.click || []) await handler();
  }
  focus() { document.activeElement = this; }
  cloneNode(deep = false) {
    const clone = new Element(this.tagName, this.literalText);
    clone.attributes = { ...this.attributes };
    clone.dataset = { ...this.dataset };
    if (deep) clone.append(...this.children.map((child) => child.cloneNode(true)));
    return clone;
  }
  querySelectorAll(selector) {
    // Only selectors currently used by app.js are implemented. Fail clearly if
    // an app change needs more selector support, rather than silently passing.
    assert.match(selector, /^(?:\.[\w-]+|#[\w-]+|\[[\w-]+\]|[\w-]+)$/,
      `Extend the test DOM adapter for selector ${selector}`);
    const matches = (element) => {
      if (selector.startsWith('.')) return element.classList.contains(selector.slice(1));
      if (selector.startsWith('#')) return element.id === selector.slice(1);
      if (selector.startsWith('[')) return element.getAttribute(selector.slice(1, -1)) !== null;
      return element.tagName === selector;
    };
    const found = [];
    const visit = (element) => {
      for (const child of element.children) {
        if (matches(child)) found.push(child);
        visit(child);
      }
    };
    visit(this);
    return found;
  }
  querySelector(selector) { return this.querySelectorAll(selector)[0] ?? null; }
}

const document = new Element('document');
document.createElement = (tag) => new Element(tag);
document.createDocumentFragment = () => new Element('#fragment');
document.getElementById = (id) => document.querySelector(`#${id}`);
document.contains = (element) => {
  while (element) {
    if (element === document) return true;
    element = element.parent;
  }
  return false;
};
document.activeElement = null;
document.hidden = false;

const stack = [document];
const voidElements = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr']);
for (const token of markup.match(/<[^>]*>|[^<]+/g)) {
  if (token.startsWith('<!')) continue;
  if (token.startsWith('</')) { stack.pop(); continue; }
  if (token.startsWith('<')) {
    const tag = token.match(/^<([\w-]+)/)[1];
    const element = new Element(tag);
    for (const match of token.matchAll(/([\w-]+)="([^"]*)"/g)) element.setAttribute(match[1], match[2]);
    if (/\shidden(?:\s|>)/.test(token)) element.hidden = true;
    if (/\sdisabled(?:\s|>)/.test(token)) element.disabled = true;
    stack.at(-1).append(element);
    if (!voidElements.has(tag)) stack.push(element);
  } else stack.at(-1).append(new Element('#text', token));
}

const id = (value) => {
  const element = document.getElementById(value);
  assert.ok(element, `Missing element #${value}`);
  return element;
};
const scenarioButton = (scenario) => {
  const button = document.querySelectorAll('[data-scenario]').find((item) => item.dataset.scenario === scenario);
  assert.ok(button, `Missing ${scenario} scenario button`);
  return button;
};
const copyFixture = (scenario) => ({ ...structuredClone(fixtures[scenario]), csrf_token: 'test-local-token' });
let overview = copyFixture('latency');
let offline = false;
let responseStatus = 200;
const requests = [];
const fetchStub = async (path, options) => {
  requests.push({ path, ...options });
  if (offline) throw new Error('Simulated connection failure');
  if (responseStatus !== 200) return { ok: false, status: responseStatus };
  if (options.method === 'POST') {
    assert.equal(options.headers['Content-Type'], 'application/json');
    assert.equal(options.headers['X-Ops-Token'], overview.csrf_token);
  }
  if (path === '/api/demo') {
    assert.equal(options.method, 'POST');
    overview = copyFixture(JSON.parse(options.body).scenario);
  } else if (path.endsWith('/ack')) {
    assert.equal(options.method, 'POST');
    assert.equal(options.body, '{}');
    const incident = overview.incidents.find((entry) => entry.id === path.split('/')[3]);
    assert.ok(incident, 'Acknowledged incident exists');
    incident.status = 'acknowledged';
    return { ok: true, json: async () => ({ ok: true }) };
  } else assert.equal(path, '/api/overview');
  return { ok: true, json: async () => structuredClone(overview) };
};

const timers = new Map();
let timerId = 0;
const window = { location: { hash: '' }, events: {}, addEventListener(name, fn) { this.events[name] = fn; } };
const context = vm.createContext({
  document, window, fetch: fetchStub, AbortController, Intl, Date, Number, JSON,
  Array, String, Boolean, Math, console,
  setTimeout: (fn, delay) => { timers.set(++timerId, { fn, delay }); return timerId; },
  clearTimeout: (timer) => timers.delete(timer),
});
const flush = () => new Promise((done) => setImmediate(done));
let passed = 0;
function pass(description) { passed += 1; console.log(`PASS ${description}`); }

const ids = document.querySelectorAll('[id]').map((element) => element.id);
assert.equal(ids.length, new Set(ids).size, 'HTML IDs are unique');
assert.doesNotMatch(markup, /\son[a-z]+\s*=/i, 'No inline event handlers');
assert.doesNotMatch(markup, /<script(?![^>]*\bsrc=)[^>]*>/i, 'No inline scripts');
assert.doesNotMatch(markup, /(?:src|href)\s*=\s*["']https?:\/\//i, 'No remote asset dependencies');
assert.doesNotMatch(app, /\b(?:innerHTML|outerHTML|insertAdjacentHTML|eval)\b/, 'No executable HTML rendering');
pass('HTML safety, unique IDs, external local assets, no unsafe HTML APIs');

vm.runInContext(app, context, { filename: 'app.js', timeout: 2000 });
await flush();
assert.equal(document.querySelectorAll('.service-card').length, fixtures.latency.services.length);
assert.equal(id('stat-open').textContent, String(fixtures.latency.stats.incidents_open));
assert.ok(document.querySelectorAll('.step').length > 0);
assert.ok(document.querySelectorAll('.evidence-item').length > 0);
assert.equal(id('error-banner').hidden, true);
assert.ok([...timers.values()].some((timer) => timer.delay === 5000), 'Five-second refresh is scheduled');
assert.equal(document.querySelector('.nav-item').getAttribute('aria-current'), 'location');
pass('initial backend payload renders metrics, incidents, evidence, steps, and refresh timer');

for (const scenario of ['errors', 'memory', 'cascade']) {
  const button = scenarioButton(scenario);
  const original = button.textContent;
  const childCount = button.childNodes.length;
  const before = requests.length;
  const firstClick = button.click();
  await button.click(); // A repeated click while disabled must not issue a second POST.
  await firstClick;
  assert.equal(id('stat-open').textContent, String(fixtures[scenario].stats.incidents_open));
  assert.equal(requests.slice(before).filter((request) => request.path === '/api/demo').length, 1);
  assert.equal(button.textContent, original);
  assert.equal(button.childNodes.length, childCount, 'Scenario icons survive loading state');
  assert.equal(button.getAttribute('aria-pressed'), 'true');
}
pass('error, memory, cascade injections send tokens once and preserve control icons');

const selected = document.querySelectorAll('.incident-item')[1];
await selected.click();
const selectedFocusKey = document.activeElement.getAttribute('data-focus-key');
const selectedId = id('incident-detail').querySelector('.incident-id').textContent;
await id('refresh-button').click();
assert.equal(id('incident-detail').querySelector('.incident-id').textContent, selectedId);
// Exercise a background refresh while the incident control itself has focus.
const replacement = document.querySelectorAll('.incident-item').find((item) => item.getAttribute('data-focus-key') === selectedFocusKey);
replacement.focus();
const pollTimer = [...timers.values()].find((timer) => timer.delay === 5000);
await pollTimer.fn();
assert.equal(document.activeElement.getAttribute('data-focus-key'), selectedFocusKey);
assert.ok(document.contains(document.activeElement));
pass('selected incident and keyboard focus survive a background refresh');

await id('ack-button').click();
assert.equal(document.getElementById('ack-button'), null);
assert.match(id('incident-detail').textContent, /Acknowledged locally/);
assert.match(id('toast').textContent, /No remediation was executed/);
pass('acknowledgement updates local incident and fetches confirmed status');

await scenarioButton('healthy').click();
assert.equal(id('stat-open').textContent, '0');
assert.match(id('incident-detail').textContent, /Quiet is a good signal/);
overview = copyFixture('recovered');
await id('refresh-button').click();
assert.equal(document.querySelectorAll('.incident-item').length, 0);
await id('filter-all').click();
assert.equal(document.querySelectorAll('.incident-item').length, fixtures.recovered.incidents.length);
assert.match(id('incident-detail').textContent, /Resolved/);
assert.equal(document.getElementById('ack-button'), null);
await id('filter-active').click();
assert.equal(document.querySelectorAll('.incident-item').length, 0);
pass('healthy empty state and Active/All filters handle real resolved incidents');

offline = true;
await id('refresh-button').click();
assert.equal(id('error-banner').hidden, false);
assert.match(id('error-message').textContent, /stale/);
assert.equal(document.querySelectorAll('.service-card').length, 3, 'Cached data survives failure');
offline = false;
await id('retry-button').click();
assert.equal(id('error-banner').hidden, true);
pass('connection failure retains stale data, then Retry restores normal status');

responseStatus = 403;
await scenarioButton('latency').click();
assert.equal(id('error-banner').hidden, false);
assert.match(id('error-message').textContent, /session token changed/);
assert.equal(scenarioButton('latency').disabled, false, 'Failed action unlocks controls');
responseStatus = 200;
await id('refresh-button').click();
assert.equal(id('error-banner').hidden, true);
pass('rejected action reports token error and unlocks controls for recovery');

overview = copyFixture('errors');
overview.mode = 'monitor';
overview.model = { enabled: true, provider: 'Ollama', model: 'test-local-model' };
const hostileText = '<img src=x onerror="alert(1)">';
overview.incidents[0].diagnosis.summary = hostileText;
await id('refresh-button').click();
assert.equal(id('scenario-panel').hidden, true);
assert.equal(id('monitor-note').hidden, false);
assert.equal(id('engine-label').textContent, 'Ollama');
assert.match(id('model-call-description').textContent, /test-local-model/);
assert.ok(id('incident-detail').textContent.includes(hostileText));
assert.equal(id('incident-detail').querySelectorAll('img').length, 0);
pass('monitor/Ollama mode is explicit and untrusted diagnosis text stays literal');

window.location.hash = '#activity';
window.events.hashchange();
assert.equal(document.querySelectorAll('.nav-item').find((item) => item.getAttribute('href') === '#activity').getAttribute('aria-current'), 'location');
window.location.hash = '';
window.events.hashchange();
assert.equal(document.querySelectorAll('.nav-item').find((item) => item.getAttribute('href') === '#overview').getAttribute('aria-current'), 'location');
pass('hash navigation and back-to-overview state update accessible navigation');

console.log(`\n${passed} dashboard contract groups passed. Browser layout and CSP enforcement are not exercised.`);
